.c-blue { background-color: rgb(13, 110, 253); border: 1px solid rgb(13, 110, 253); }
.c-blue:hover { background-color: rgb(11, 94, 215); border-color: rgb(11, 94, 215); }
.c-white { background-color: rgb(255, 255, 255); border: 1px solid rgb(222, 226, 230); color: rgb(102, 102, 102); transition: 0.3s; }
.c-white:hover, .c-white:focus, .c-white:active { color: rgb(51, 51, 51); background-color: rgb(230, 230, 230); border-color: rgb(173, 173, 173); }
.hn-tip { width: 100%; position: fixed; left: 0px; top: 0px; z-index: 987654321; }
.hn-mask { width: 100%; height: 100%; position: fixed; left: 0px; top: 0px; visibility: hidden; opacity: 0; z-index: 987654321; background-color: rgba(0, 0, 0, 0.1); transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1); }
.hn-tip .hn-mask { background-color: transparent; }
.hn-msg { position: fixed; left: 50%; top: 50%; z-index: 987654321; max-width: 500px; transform: translate(-50%, -50%) scale(0.5); opacity: 0; visibility: hidden; font-size: 14px; color: rgb(255, 255, 255); background-color: rgba(0, 0, 0, 0.6); border-radius: 2px; padding: 12px 25px; transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1); }
.hn-tip.show .hn-mask { visibility: visible; opacity: 1; }
.hn-tip.show .hn-msg { transform: translate(-50%, -50%) scale(1); opacity: 1; visibility: visible; }
.hn-load { width: 100%; position: fixed; left: 0px; top: 0px; z-index: 987654321; }
.hn-load-cont { position: fixed; left: 50%; top: 50%; z-index: 987654321; max-width: 500px; transform: translate(-50%, -50%) scale(0.5); opacity: 0; visibility: hidden; transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1); }
.hn-load-icon { width: 32px; height: 32px; margin: 0px auto; background-image: url("/static/load.gif"); background-repeat: no-repeat; background-position: 100% 100%; }
.hn-load-title { font-size: 14px; color: rgb(51, 51, 51); text-align: center; margin-top: 10px; }
.hn-load.show .hn-mask { visibility: visible; opacity: 1; }
.hn-load.show .hn-load-cont { transform: translate(-50%, -50%) scale(1); opacity: 1; visibility: visible; }
.hn-confirm { width: 100%; position: fixed; left: 0px; top: 0px; z-index: 987654321; border-radius: 2px 2px 0px 0px; }
.hn-confirm-dialog { width: auto; min-width: 300px; position: fixed; left: 0px; top: 0px; z-index: 987654321; transform: scale(0.5); opacity: 0; visibility: hidden; background-color: rgb(255, 255, 255); transition: transform 0.3s cubic-bezier(0.25, 0.1, 0.25, 1), opacity 0.3s cubic-bezier(0.25, 0.1, 0.25, 1); }
.hn-confirm-title { padding: 0px 80px 0px 20px; height: 46px; line-height: 46px; border-bottom: 1px solid rgb(240, 240, 240); font-size: 14px; color: rgb(51, 51, 51); overflow: hidden; cursor: move; user-select: none; }
.hn-confirm-cont { width: 100%; position: relative; padding: 20px; line-height: 24px; word-break: break-all; overflow: hidden; font-size: 14px; }
.hn-confirm-btns { text-align: right; padding: 0px 15px 12px; user-select: none; font-size: 0px; }
.hn-confirm-close { font-size: 16px; color: rgb(102, 102, 102); position: absolute; right: 0px; top: 0px; line-height: 46px; width: 46px; text-align: center; cursor: pointer; font-weight: bold; transition: 0.3s; user-select: none; }
.hn-confirm-close:hover { opacity: 0.7; }
.hn-confirm-btns .c-btn { margin-left: 10px; }
.hn-confirm-btns .c-btn:first-child { margin-left: 0px; }
.hn-confirm.show .hn-mask { visibility: visible; opacity: 1; }
.hn-confirm.show .hn-confirm-dialog { transform: scale(1); opacity: 1; visibility: visible; }
.hn-html { width: 100%; position: fixed; left: 0px; top: 0px; z-index: 987654321; border-radius: 2px 2px 0px 0px; }
.hn-html-dialog { width: auto; min-width: 300px; position: fixed; left: 0px; top: 0px; z-index: 987654321; transform: scale(0.5); opacity: 0; visibility: hidden; background-color: rgb(255, 255, 255); transition: transform 0.3s cubic-bezier(0.25, 0.1, 0.25, 1), opacity 0.3s cubic-bezier(0.25, 0.1, 0.25, 1); }
.hn-html-title { padding: 0px 80px 0px 10px; height: 46px; line-height: 46px; border-bottom: 1px solid rgb(240, 240, 240); font-size: 14px; color: rgb(51, 51, 51); overflow: hidden; cursor: move; user-select: none; }
.hn-html-cont { width: 100%; position: relative; padding: 10px; line-height: 24px; word-break: break-all; overflow: auto; font-size: 14px; }
.hn-html-close { font-size: 16px; color: rgb(102, 102, 102); position: absolute; right: 0px; top: 0px; line-height: 46px; width: 46px; text-align: center; cursor: pointer; font-weight: bold; transition: 0.3s; user-select: none; }
.hn-html-close:hover { opacity: 0.7; }
.hn-html.show .hn-mask { visibility: visible; opacity: 1; }
.hn-html.show .hn-html-dialog { transform: scale(1); opacity: 1; visibility: visible; }
